"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["25752"],{22981(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>p,contentTitle:()=>o,toc:()=>d,assets:()=>h});var a=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-fetch-certs-path","title":"Fetch certificate path","description":"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant\'s certificate path.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs-path.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-fetch-certs-path","permalink":"/docs/pr-48/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs-path","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Fetch certificate path","sidebar_label":"Fetch certificate path","sidebar_class_name":"api-method api-method--post","description":"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant\'s certificate path.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Fetch certificate","permalink":"/docs/pr-48/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs"},"next":{"title":"Update certificate (v2, no passcode)","permalink":"/docs/pr-48/docs/nhcx/v1/api/registry/endpoints/registry-v2-update-cert"}}'),i=n(62540),r=n(43023),s=n(52563),c=JSON.parse('{"id":"registry_fetch_certs_path","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/fetch/certs/path","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Fetch certificate path","title":"Fetch certificate path","description":"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant\'s certificate path.\\n\\n### Business purpose\\n\\nThe registry stores a participant\'s encryption certificate as a URI or file path in the encryption_cert field, and this endpoint exposes that reference for a given participant. It exists alongside /fetch/certs, which the Integration Handbook names as the call to use when obtaining key material for encryption. Both serve the same underlying need, resolving a counterparty\'s public key before building a JWE, but the OpenAPI documents them identically and does not describe how their returned strings differ.\\n\\n### When to use\\n\\nUse it only if your NHCX instance tells you to. For encryption, use `/fetch/certs`.\\n\\n### Preconditions\\n\\n- You have a valid access token in the `bearer_auth` header.\\n- You send the target\'s code as `participantid`.\\n\\n### Postconditions\\n\\nYou get a string back. What it contains beyond a certificate path is not documented.\\n\\n### Common mistakes\\n\\n- Treating the answer as the certificate that `/fetch/certs` returns.\\n- Using this instead of `/fetch/certs` without instructions from your instance.\\n\\n### Best practices\\n\\n- Prefer /fetch/certs for obtaining key material; use this endpoint only where the instance documents a use for the path form.\\n- If you do use it, log the returned string shape once so a change in behaviour is noticed.\\n- Apply the same 24-hour cache discipline keyed by participantid.\\n- Keep both calls behind one client function so the choice is a configuration switch.\\n\\n### Related scenario\\n\\nAn integrator building a registry inspection tool for a TPA wants to show, for each payer, where the registry references its certificate as well as the certificate itself. The tool obtains a Bearer token, calls /fetch/certs/path with the payer\'s participant code and displays the returned path string, then calls /fetch/certs for the PEM used for actual encryption. The production claims engine itself only uses /fetch/certs, as the Integration Handbook prescribes, before each /v1/claim/submit.\\n\\n### Specification\\n\\nChapter [Finding participants and policies](/docs/nhcx/v1/getting-started/finding-participants-and-policies) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[{"name":"Accept","required":true,"description":"Always `application/json` on the participant service.","example":"application/json","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participantid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participantid":"<payer participant code>"},"responses":[{"status":"200","description":"HTTP 200 with a string body.","example":{"_contentType":"string","_body":"<certificate path string as declared by the OpenAPI 200 response>"},"synthesised":false,"fields":[{"name":"_contentType","type":"string","required":false,"description":""},{"name":"_body","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participantid\\": \\"<payer participant code>\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participantid\\": \\"<payer participant code>\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Accept\\": \\"application/json\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"participantid\\": \\"<payer participant code>\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Accept\\": \\"application/json\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"participantid\\": \\"<payer participant code>\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Accept\\", \\"application/json\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"participantid\\": \\"<payer participant code>\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Accept: application/json\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"participantid\\": \\"<payer participant code>\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"participantid\\": \\"<payer participant code>\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Accept\\", \\"application/json\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Accept\\", \\"application/json\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"participantid\\": \\"<payer participant code>\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Accept\'] = \'application/json\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"participantid\\": \\"<payer participant code>\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Fetch certificate path",sidebar_label:"Fetch certificate path",sidebar_class_name:"api-method api-method--post",description:"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant's certificate path.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},o,h={},d=[];function l(e){return(0,i.jsx)(s.Ay,{operation:c})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);